mapper.select:
select od.id as id,od.create_time as createTime,od.order_sn as orderSn,od.user_id as userId,od.goods_id as goodsId,od.price as price,od.amount as amount, od.order_status as orderStatus,od.pay_type as payType, goods.name as goodsName,goods.image as goodsImg,goods.period as period, su.nickname as userName,su.avatar as userAvatar,su.phone as userPhone from integral_goods_order od left join integral_goods goods on goods.id = od.goods_id left join sys_user su on su.id = od.user_id WHERE 1=1
AND od.user_id = #{params.userId}
AND od.pay_type = #{params.payType}
AND od.order_status = #{params.orderStatus}
and ( su.nickname like CONCAT('%',#{params.keyword},'%') or su.phone like CONCAT('%',#{params.keyword},'%') or goods.name like CONCAT('%',#{params.keyword},'%') )
order by od.create_time desc
